import{_ as t,o as a,c as o,a0 as p}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"分析化学手册（第二版）第一分册：基础知识与安全知识","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/自学阅读/分析化学手册（第二版）第一分册：基础知识与安全知识.md","filePath":"中山大学/自学阅读/分析化学手册（第二版）第一分册：基础知识与安全知识.md"}'),d={name:"中山大学/自学阅读/分析化学手册（第二版）第一分册：基础知识与安全知识.md"};function c(l,e,n,s,r,i){return a(),o("div",null,[...e[0]||(e[0]=[p(`<h1 id="分析化学手册-第二版-第一分册-基础知识与安全知识" tabindex="-1">分析化学手册（第二版）第一分册：基础知识与安全知识 <a class="header-anchor" href="#分析化学手册-第二版-第一分册-基础知识与安全知识" aria-label="Permalink to &quot;分析化学手册（第二版）第一分册：基础知识与安全知识&quot;">​</a></h1><p>化学工业出版社</p><h2 id="第一章-分析化学中常用数据及表解" tabindex="-1">第一章 分析化学中常用数据及表解 <a class="header-anchor" href="#第一章-分析化学中常用数据及表解" aria-label="Permalink to &quot;第一章 分析化学中常用数据及表解&quot;">​</a></h2><h3 id="第四节-离子的基本参数" tabindex="-1">第四节 离子的基本参数 <a class="header-anchor" href="#第四节-离子的基本参数" aria-label="Permalink to &quot;第四节 离子的基本参数&quot;">​</a></h3><br><h5 id="离子半径" tabindex="-1">离子半径 <a class="header-anchor" href="#离子半径" aria-label="Permalink to &quot;离子半径&quot;">​</a></h5><p><strong>结晶离子半径</strong></p><p>晶体中正负离子的接触半径</p><p>我们把晶体中的正负离子看作相互接触的刚性球体，相邻正负离子相切，则正负离子中心间的距离<code>d</code>就是正负离子的半径之和</p><blockquote><p>d = r1 + r2</p></blockquote><p><code>d</code>可以通过X射线分析实验测量</p><p><strong>作用：</strong></p><ol><li>可以用来判断晶体结构类型（半径比规则）</li></ol><p>阳离子要填进阴离子堆积出来的空隙里，阳离子半径 / 阴离子半径<code>r+/r-</code>决定配位数、晶体构型。</p><p>绝大多数离子晶体，阳离子半径远小于阴离子半径</p><blockquote><p>阴离子：得电子，电子云膨胀，体积大</p></blockquote><blockquote><p>阳离子：失电子，丢掉外层电子，体积小</p></blockquote><p>当然也有反过来的情况：阳离子比阴离子大，比如氟化物、铯盐：CsF</p><blockquote><p>此时的半径比比值＞1，已经超出规则设计区间，半径比规则不再适用</p></blockquote><table tabindex="0"><thead><tr><th>r+ / r-</th><th>阳离子配位数</th><th>晶体构型</th><th>例子</th></tr></thead><tbody><tr><td>0.225‑0.414</td><td>4</td><td>闪锌矿 / 纤锌矿 (ZnS 型)</td><td>ZnS</td></tr><tr><td>0.414‑0.732</td><td>6</td><td>NaCl 型</td><td>NaCl、MgO</td></tr><tr><td>0.732‑1.0</td><td>8</td><td>CsCl 型</td><td>CsCl</td></tr></tbody></table><ol start="2"><li>计算晶胞参数（a，b，c，α，β，γ）</li></ol><p>a，b，c是晶格常数，α，β，γ是轴间角（轴角）</p><p>晶胞边长和离子相切关系挂钩，可以直接算出晶胞边长<code>a</code></p><p>例：NaCl晶胞：棱边上阴阳离子相切，<code>a=2·(r(Na+)+r(Cl-))</code></p><p>代入数值：<code>a=566pm</code>，和实验值<code>564pm</code>非常接近。</p><blockquote><p>用途：预测晶胞大小，算晶体密度。ρ=Z（化学式单元数）M（化学式摩尔质量）/（NA）·a³（立方晶胞）</p></blockquote><h5 id="离子的活度系数-活度因子" tabindex="-1">离子的活度系数（活度因子） <a class="header-anchor" href="#离子的活度系数-活度因子" aria-label="Permalink to &quot;离子的活度系数（活度因子）&quot;">​</a></h5><p>很多中文教材：<code>f</code>叫活度系数；<code>γ</code>叫平均离子活度系数</p><p>活度系数<code>f</code>的大小是表示电解质溶液中，离子之间互相牵制作用，在稀溶液中，活度系数可看作只与溶液的离子的强度有关</p><blockquote><p>注意：单离子活度系数<code>f</code>实验不能单独测量，只能理论计算；实际测量得到的是平均离子活度系数<code>γ</code>。</p></blockquote><p>离子强度是代表溶液中电场强弱的尺度，其关系与离子浓度、离子电荷的关系如下：</p><blockquote><p>I = (1/2)·∑(mi)·(zi)²</p></blockquote><p><code>m</code>代表溶液中各离子的质量摩尔浓度；<code>z</code>代表各离子的电荷数</p><p>溶液里带电离子越多、电荷越高，静电场越强，离子之间拉扯越厉害，偏离理想溶液越严重</p><p>在稀溶液中，质量摩尔浓度可视为与物质的量浓度相等，所以计算的时候可以直接以物质的量浓度代入</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>b：质量摩尔浓度，单位mol/kg，每1kg溶剂中溶质的物质的量</span></span>
<span class="line"><span>c：物质的量浓度，单位mol/L，每1L溶液中溶质的物质的量</span></span>
<span class="line"><span>b = n溶质/m溶剂，c = n溶质/V溶液</span></span>
<span class="line"><span>稀水溶液，溶质很少</span></span>
<span class="line"><span>溶液总质量 ≈ 溶剂的质量，则b ≈ c</span></span></code></pre></div><h5 id="德拜‐休克尔极限公式" tabindex="-1">德拜‑休克尔极限公式 <a class="header-anchor" href="#德拜‐休克尔极限公式" aria-label="Permalink to &quot;德拜‑休克尔极限公式&quot;">​</a></h5><p>基于德拜-休克尔离子互吸理论（非缔合式电解质理论），假设强电解质完全电离，溶液中离子间主要作用力为库仑力，溶剂被视为连续介质，忽略水化作用和介电常数变化，同时引入了离子氛概念</p><p>离子氛，亦称离子云，是处理电解质溶液中离子相互作用的一种模型，指在每个中心离子周围存在一个球形对称的电荷分布区域。离子氛可理解为溶液中某离子周围存在的反离子的长时间平均累积。（百度百科）</p><p>lg(γi) = -A·(zi)²·(I)^(1/2)</p><blockquote><p>A：与温度和压力有关的常数</p></blockquote><p>核心作用:计算极稀强电解质溶液中离子的活度系数<code>γ</code></p><p><strong>背景</strong></p><p>电解质溶液，离子之间有静电相互作用</p><ul><li>浓度c（分析浓度）：理论浓度</li><li>活度ai=γi·(bi/b°)：离子真正起作用的有效浓度</li></ul><p>热力学平衡常数、电极电势、溶解度计算，严格来说需要用活度，不能直接用浓度</p><p>稀溶液里<code>γ</code>≈1，活度≈浓度，可以直接代浓度；如果离子强度不为0，<code>γ</code>偏离1，就要校正</p><p>德拜‑休克尔极限公式可以算校正因子<code>γ</code></p><p><strong>修正</strong></p><p>德拜‑休克尔极限公式并不是经验公式，而是理论推导出来的</p><p>所以根据前提条件，这条公式只有在极稀溶液下才能够近似使用</p><p>为此，我们可以使用德拜‑休克尔修正式</p><p>德拜‑休克尔修正式（戴维斯修正公式）是半经验公式，它就可以在稍高浓度的溶液中使用</p>`,53)])])}const _=t(d,[["render",c]]);export{b as __pageData,_ as default};
